head.b:skin:
/*!************************************************
 * Blogger Template Style
 * Name: دهشة موثّقة
 **************************************************/
/*!

=========================================================
  قالب «دهشة موثّقة» — قالب بلوجر كلاسيكي أنيق
  الإصدار 1.1.0
  تصميم: تخطيط بسيط، ألوان كلاسيكية، خطوط نسخية (Serif)
  يعمل بخصائص CSS المنطقية لذلك يدعم العربية (RTL) والإنجليزية (LTR)
=========================================================

Variable definitions
====================

<Variable name="keycolor" description="اللون الرئيسي (ذهبي كلاسيكي)" type="color" default="#9c7c48" value="#9c7c48"/>
<Variable name="accent.dark.color" description="اللون الرئيسي الغامق" type="color" default="#7d6135" value="#7d6135"/>
<Variable name="body.background.color" description="لون خلفية الصفحة" type="color" default="#f7f4ee" value="#f7f4ee"/>
<Variable name="posts.background.color" description="لون خلفية البطاقات" type="color" default="#ffffff" value="#ffffff"/>
<Variable name="posts.title.color" description="لون العناوين" type="color" default="#1f1c19" value="#1f1c19"/>
<Variable name="body.text.color" description="لون النص" type="color" default="#4a443c" value="#4a443c"/>
<Variable name="muted.color" description="لون النص الثانوي" type="color" default="#8c8578" value="#8c8578"/>
<Variable name="border.color" description="لون الحدود والفواصل" type="color" default="#e8e1d5" value="#e8e1d5"/>
<Variable name="body.link.color" description="لون الروابط" type="color" default="$(keycolor)" value="#9c7c48"/>
<Variable name="body.link.hover.color" description="لون الروابط عند المرور" type="color" default="$(accent.dark.color)" value="#7d6135"/>
<Variable name="body.text.font" description="خط النص الأساسي" type="font" default="16px Almarai, sans-serif" value="16px Almarai, sans-serif"/>
<Variable name="posts.title.font" description="خط عناوين المشاركات" type="font" default="700 34px Amiri, serif" value="700 34px Amiri, serif"/>
<Variable name="blog.title.font" description="خط عنوان المدونة" type="font" default="700 40px Amiri, serif" value="700 40px Amiri, serif"/>
<Variable name="widget.title.font" description="خط عناوين الأدوات" type="font" default="700 19px Amiri, serif" value="700 19px Amiri, serif"/>
<Variable name="footer.background.color" description="خلفية التذييل" type="color" default="#23292f" value="#23292f"/>
<Variable name="footer.text.color" description="نص التذييل" type="color" default="#b8c0c7" value="#b8c0c7"/>
<Variable name="footer.link.color" description="روابط التذييل" type="color" default="#ffffff" value="#ffffff"/>
<Variable name="layout.width" description="أقصى عرض للتخطيط" type="length" min="900px" max="1700px" default="1180px" value="1180px"/>
<Variable name="sidebar.width" description="عرض الشريط الجانبي" type="length" min="200px" max="480px" default="320px" value="320px"/>
*/

/* ============================================================
   1) تصفير وإعدادات أساسية
   ============================================================ */
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;text-size-adjust:100%;scroll-behavior:smooth}
body{
  margin:0;
  background-color:$(body.background.color);
  color:$(body.text.color);
  font:$(body.text.font);
  font-family:$(body.text.font.family);
  font-size:$(body.text.font.size);
  line-height:1.9;
  min-height:100vh;
  overflow-wrap:break-word;
  word-wrap:break-word;
}
img{max-width:100%;height:auto;border:0;vertical-align:middle}
img[src='']{visibility:hidden}
svg{display:inline-block;vertical-align:middle;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
a{color:$(body.link.color);text-decoration:none;transition:color .2s ease}
a:hover,a:focus{color:$(body.link.hover.color)}
a:focus-visible,button:focus-visible,input:focus-visible{outline:2px solid $(keycolor);outline-offset:2px}
h1,h2,h3,h4,h5,h6{
  font-family:$(posts.title.font.family);
  color:$(posts.title.color);
  line-height:1.4;
  margin:0 0 .7em;
  font-weight:700;
}
p{margin:0 0 1.2em}
hr{border:0;border-top:1px solid $(border.color);margin:2em 0}
table{border-collapse:collapse;width:100%;margin:1.5em 0;font-size:.97em}
th,td{border:1px solid $(border.color);padding:10px 14px;text-align:start}
th{background:rgba(0,0,0,.03);color:$(posts.title.color);font-weight:700}
blockquote{
  margin:1.8em 0;
  padding:6px 26px;
  border-inline-start:3px solid $(keycolor);
  font-family:$(posts.title.font.family);
  font-size:1.15em;
  font-style:italic;
  color:$(posts.title.color);
}
blockquote p:last-child{margin-bottom:0}
code,kbd,pre,samp{font-family:Menlo,Consolas,"Courier New",monospace;direction:ltr;text-align:left}
code{background:rgba(0,0,0,.045);border-radius:3px;padding:.15em .45em;font-size:.9em}
pre{background:#2b2b2b;color:#f2ede4;border-radius:4px;padding:18px 20px;overflow:auto;font-size:.92em;line-height:1.7}
pre code{background:0 0;padding:0;color:inherit}
.hidden,.invisible,.item-control,.quickedit,.widget-item-control,.feed-links,.blog-feeds,#navbar,.navbar{display:none}
.clearboth,.clear{clear:both}
.status-msg-body,.status-msg-bg{display:none}

/* رابط تجاوز المحتوى */
.skip-link{
  background:$(posts.title.color);color:#fff;inset-inline-start:12px;padding:10px 18px;position:absolute;
  top:-100px;z-index:9999;transition:top .2s;border-radius:0 0 4px 4px;font-size:14px
}
.skip-link:focus{top:0;color:#fff}

.container{width:100%;max-width:$(layout.width);margin-inline:auto;padding-inline:18px}

/* ============================================================
   2) الترويسة
   ============================================================ */
.site-header{background:$(posts.background.color);border-bottom:1px solid $(border.color);position:relative;z-index:60}
.header-inner{padding-block:46px 38px;text-align:center}
.header-logo{display:inline-block;max-width:420px}
.header-logo img{margin-inline:auto;max-height:130px;width:auto}
.header-widget h1,.header-widget .site-title,.header-widget p.site-title{
  font:$(blog.title.font);
  font-family:$(blog.title.font.family);
  font-size:$(blog.title.font.size);
  letter-spacing:.01em;
  margin:0;
  color:$(posts.title.color);
}
.header-widget h1 a,.header-widget .site-title a{color:$(posts.title.color)}
.header-widget h1 a:hover,.header-widget .site-title a:hover{color:$(keycolor)}
.site-description{color:$(muted.color);font-size:15px;letter-spacing:.04em;margin:12px auto 0;max-width:640px}
.header-ornament{display:flex;align-items:center;justify-content:center;gap:12px;color:$(keycolor);margin-top:22px;opacity:.85}
.header-ornament::before,.header-ornament::after{content:"";height:1px;width:64px;background:currentColor;opacity:.55}
.header-behind{padding:56px 24px;border-radius:2px;background-position:center;background-size:cover;position:relative}
.header-behind::before{content:"";position:absolute;inset:0;background:rgba(0,0,0,.42)}
.header-behind>*{position:relative;z-index:1;color:#fff}
.header-behind .site-title a{color:#fff}
.header-behind .site-description{color:rgba(255,255,255,.88)}

/* ============================================================
   3) شريط التنقل
   ============================================================ */
.site-nav{
  background:$(posts.background.color);
  border-bottom:1px solid $(border.color);
  box-shadow:0 6px 18px -14px rgba(0,0,0,.35);
  position:sticky;top:0;z-index:80
}
.nav-inner{
  align-items:center;display:flex;flex-wrap:wrap;gap:8px 22px;justify-content:center;
  min-height:64px;padding-block:8px;position:relative
}
.nav-toggle-checkbox{display:none}
.nav-toggle{color:$(posts.title.color);cursor:pointer;display:none;padding:10px}
.site-nav ul{display:flex;flex-wrap:wrap;gap:2px;justify-content:center;list-style:none;margin:0;padding:0}
.site-nav li a{
  border-bottom:2px solid transparent;color:$(body.text.color);display:block;
  font-size:14.5px;letter-spacing:.02em;padding:18px 15px
}
.site-nav li a:hover,.site-nav li.selected>a,.site-nav li a.current-item{color:$(keycolor);border-bottom-color:$(keycolor)}
.site-nav .widget-title{display:none}
/* البحث داخل .nav-inner: flex-basis:100% يجعله يأخذ سطرًا كاملًا بعرض الصفحة */
.nav-search{
  align-items:center;background:$(body.background.color);border:1px solid $(border.color);
  border-radius:999px;display:flex;flex-basis:100%;flex-grow:1;gap:4px;padding:5px;width:100%;
  transition:border-color .25s ease,box-shadow .25s ease
}
.nav-search:focus-within{border-color:$(keycolor);box-shadow:0 0 0 3px rgba(156,124,72,.13)}
.nav-search button{
  align-items:center;background:$(keycolor);border:0;border-radius:50%;color:#fff;cursor:pointer;
  display:flex;flex:0 0 38px;height:38px;justify-content:center;transition:background .2s ease;width:38px
}
.nav-search button:hover{background:$(accent.dark.color)}
.nav-search svg{height:16px;width:16px;stroke-width:2}
.nav-search input{
  background:0 0;border:0;color:$(body.text.color);flex:1 1 auto;font:inherit;font-size:15px;
  min-width:0;outline:0;padding:8px 16px;width:auto
}
.nav-search input::placeholder{color:$(muted.color)}
.search-hint{
  color:$(muted.color);flex:0 0 auto;font-size:12.5px;letter-spacing:.02em;
  opacity:.75;padding-inline-end:18px
}

/* ============================================================
   4) التخطيط العام
   ============================================================ */
.site-main{padding-block:44px 60px}
.layout-grid{align-items:start;display:grid;gap:46px;grid-template-columns:minmax(0,1fr) $(sidebar.width)}
.content-area{min-width:0}
.sidebar{min-width:0}

/* شريط نتائج البحث/الأرشيف/التسميات */
.results-bar{
  align-items:center;background:$(posts.background.color);border:1px solid $(border.color);
  border-inline-start:3px solid $(keycolor);display:flex;flex-wrap:wrap;gap:10px;
  justify-content:space-between;margin-bottom:32px;padding:16px 22px
}
.results-bar .results-text{color:$(muted.color);font-size:15px}
.results-bar .results-text b,.results-bar .results-text .label{color:$(posts.title.color)}
.results-bar a{font-size:14px;letter-spacing:.02em}

/* ============================================================
   5) قائمة المشاركات (الصفحة الرئيسية والأرشيف)
   ============================================================ */
.post-feed{display:grid;gap:40px}
.post-card{
  background:$(posts.background.color);
  border:1px solid $(border.color);
  border-radius:2px;
  display:grid;
  grid-template-columns:300px minmax(0,1fr);
  overflow:hidden;
  transition:box-shadow .3s ease,transform .3s ease
}
.post-card:hover{box-shadow:0 22px 44px -30px rgba(31,28,25,.45);transform:translateY(-2px)}
.post-card.no-thumb{grid-template-columns:minmax(0,1fr)}
.post-card .post-thumb{display:block;overflow:hidden;position:relative}
.post-card .post-thumb img{aspect-ratio:4/3;height:100%;object-fit:cover;transition:transform .5s ease;width:100%}
.post-card:hover .post-thumb img{transform:scale(1.03)}
.post-card .post-body-wrap{padding:30px 34px 32px}
.post-labels{display:flex;flex-wrap:wrap;gap:8px;list-style:none;margin:0 0 12px;padding:0}
.post-labels a,.post-labels span{
  color:$(keycolor);font-size:12px;letter-spacing:.12em;text-transform:uppercase
}
.post-labels a:hover{color:$(accent.dark.color)}
.post-card .entry-title{font-size:27px;line-height:1.45;margin:0 0 12px}
.post-card .entry-title a{color:$(posts.title.color)}
.post-card .entry-title a:hover{color:$(keycolor)}
.post-meta{color:$(muted.color);display:flex;flex-wrap:wrap;font-size:13.5px;gap:6px 18px;margin-bottom:14px}
.post-meta span,.post-meta a{align-items:center;color:$(muted.color);display:inline-flex;gap:6px}
.post-meta a:hover{color:$(keycolor)}
.post-meta svg{height:15px;width:15px;opacity:.8}
.post-snippet{color:$(body.text.color);line-height:1.95;margin:0 0 18px}
.post-snippet p{margin:0}
.post-snippet{-webkit-box-orient:vertical;-webkit-line-clamp:3;display:-webkit-box;overflow:hidden}
.read-more{
  align-items:center;display:inline-flex;font-size:13.5px;font-weight:700;gap:8px;
  letter-spacing:.06em;text-transform:uppercase
}
.read-more::after{content:"\2190";font-size:15px;transition:transform .25s ease}
.read-more:hover::after{transform:translateX(-4px)}
html[dir=ltr] .read-more::after{content:"\2192"}
html[dir=ltr] .read-more:hover::after{transform:translateX(4px)}

/* ============================================================
   6) صفحة المشاركة / الصفحة الثابتة
   ============================================================ */
.entry{background:$(posts.background.color);border:1px solid $(border.color);padding:46px clamp(20px,4.6vw,58px) 40px}
.entry-header{margin-bottom:26px;text-align:center}
.entry-title{font:$(posts.title.font);font-family:$(posts.title.font.family);font-size:$(posts.title.font.size);margin:0 0 16px}
.entry-header .post-meta{justify-content:center}
.entry-header .post-labels{justify-content:center}
.entry-divider{align-items:center;color:$(keycolor);display:flex;gap:12px;justify-content:center;margin:6px 0 26px;opacity:.8}
.entry-divider::before,.entry-divider::after{content:"";height:1px;width:54px;background:currentColor;opacity:.55}
.entry-content{font-size:$(body.text.font.size * 1.0625);line-height:2.05;overflow-wrap:break-word}
.entry-content p{margin-bottom:1.4em}
.entry-content h2,.entry-content h3,.entry-content h4{margin:1.9em 0 .8em}
.entry-content h2{font-size:1.62em;padding-bottom:.28em;position:relative}
.entry-content h2::after{background:$(keycolor);content:"";height:2px;inset-inline-start:0;position:absolute;bottom:0;width:52px}
.entry-content h3{font-size:1.32em}
.entry-content h4{font-size:1.12em}
.entry-content ul,.entry-content ol{margin:0 0 1.4em;padding-inline-start:1.5em}
.entry-content li{margin-bottom:.5em}
.entry-content img{border-radius:2px;margin:1.6em auto;height:auto}
.entry-content a{border-bottom:1px solid rgba(156,124,72,.35)}
.entry-content a:hover{border-bottom-color:$(keycolor)}
.entry-content .separator{margin:1.6em 0}
.entry-content .separator a{border:0}
.entry-content iframe{max-width:100%}
.entry-content .tr-caption,.entry-content figcaption{color:$(muted.color);font-size:.86em;font-style:italic;text-align:center}

/* التسميات أسفل المشاركة */
.entry-labels{align-items:center;display:flex;flex-wrap:wrap;gap:10px;margin-top:34px}
.entry-labels .labels-title{color:$(muted.color);font-size:13px;letter-spacing:.06em}
.entry-labels a{
  border:1px solid $(border.color);border-radius:999px;color:$(body.text.color);
  font-size:13.5px;padding:5px 16px;transition:all .2s ease
}
.entry-labels a:hover{background:$(keycolor);border-color:$(keycolor);color:#fff}

/* أزرار المشاركة */
.share-box{border-bottom:1px solid $(border.color);border-top:1px solid $(border.color);margin-top:34px;padding:20px 0}
.share-box .share-title{align-items:center;color:$(muted.color);display:flex;font-size:13px;gap:8px;justify-content:center;letter-spacing:.08em;margin-bottom:14px}
.share-list{display:flex;flex-wrap:wrap;gap:10px;justify-content:center;list-style:none;margin:0;padding:0}
.share-list a{
  border:1px solid $(border.color);border-radius:999px;color:$(body.text.color);
  font-size:13px;padding:5px 15px;transition:all .2s ease
}
.share-list a:hover{background:$(posts.title.color);border-color:$(posts.title.color);color:#fff}

/* صندوق الكاتب */
.author-box{align-items:center;background:rgba(0,0,0,.02);display:flex;gap:20px;margin-top:34px;padding:24px}
.author-box img{border-radius:50%;height:76px;object-fit:cover;width:76px}
.author-box .author-name{color:$(posts.title.color);font-family:$(posts.title.font.family);font-size:19px;margin:0 0 4px}
.author-box .author-about{color:$(muted.color);font-size:14.5px;line-height:1.8;margin:0}

/* التنقل بين المشاركات */
.post-pager{display:grid;gap:1px;grid-template-columns:1fr 1fr;margin-top:34px}
.post-pager a{
  background:rgba(0,0,0,.02);border:1px solid $(border.color);color:$(body.text.color);
  display:block;padding:20px 24px;transition:background .2s ease
}
.post-pager a:hover{background:$(posts.background.color)}
.post-pager .pager-label{color:$(muted.color);display:block;font-size:12.5px;letter-spacing:.1em;margin-bottom:6px;text-transform:uppercase}
.post-pager .pager-title{color:$(posts.title.color);font-family:$(posts.title.font.family);font-size:17px;line-height:1.6}
.post-pager .next{text-align:end}

/* ترقيم الصفحات */
.blog-pager{display:flex;gap:14px;justify-content:center;margin-top:44px}
.blog-pager a{
  border:1px solid $(border.color);color:$(posts.title.color);font-size:14px;
  letter-spacing:.04em;padding:11px 26px;transition:all .22s ease
}
.blog-pager a:hover{background:$(keycolor);border-color:$(keycolor);color:#fff}

/* لا توجد مشاركات */
.no-posts{background:$(posts.background.color);border:1px solid $(border.color);padding:60px 30px;text-align:center}
.no-posts h2{font-size:26px;margin-bottom:10px}
.no-posts p{color:$(muted.color);margin-bottom:22px}

/* ============================================================
   7) الأدوات (الشريط الجانبي وأي مكان آخر)
   ============================================================ */
.widget{background:$(posts.background.color);border:1px solid $(border.color);margin-bottom:30px;padding:26px 24px}
.widget .widget-title{
  font:$(widget.title.font);font-family:$(widget.title.font.family);font-size:$(widget.title.font.size);
  letter-spacing:.02em;margin:0 0 22px;padding-bottom:16px;position:relative;text-align:center
}
.widget .widget-title::after{background:$(keycolor);bottom:0;content:"";height:2px;left:50%;position:absolute;transform:translateX(-50%);width:40px}
.widget .widget-title span{color:$(posts.title.color)}
.widget ul{list-style:none;margin:0;padding:0}
.widget li{margin-bottom:12px}
.widget li:last-child{margin-bottom:0}
.widget a{color:$(body.text.color)}
.widget a:hover{color:$(keycolor)}
.widget img{max-width:100%}

/* أدوات HTML/نص */
.widget .widget-content{line-height:1.9;overflow-wrap:break-word}
.widget .widget-content p:last-child{margin-bottom:0}
.widget-empty{color:$(muted.color);font-size:14px;margin:0;text-align:center}

/* الملف الشخصي */
.widget.Profile{text-align:center}
.widget.Profile .profile-img{border-radius:50%;height:104px;margin:0 auto 16px;object-fit:cover;width:104px}
.widget.Profile .default-avatar-wrapper svg{color:$(border.color);height:104px;width:104px}
.widget.Profile .profile-name{color:$(posts.title.color);font-family:$(posts.title.font.family);font-size:20px;margin-bottom:8px}
.widget.Profile .profile-textblock{color:$(muted.color);font-size:14.5px;line-height:1.9;margin:0 0 16px}
.widget.Profile .profile-data.location{color:$(muted.color);font-size:13.5px;margin-bottom:10px}
.widget.Profile .visit-profile{
  border:1px solid $(border.color);border-radius:999px;color:$(keycolor);display:inline-block;
  font-size:13px;letter-spacing:.04em;padding:6px 20px;transition:all .2s ease
}
.widget.Profile .visit-profile:hover{background:$(keycolor);border-color:$(keycolor);color:#fff}
.widget.Profile .team-list li{align-items:center;display:flex;gap:14px;text-align:start}
.widget.Profile .team-list img{border-radius:50%;height:52px;width:52px}

/* المشاركات الشائعة */
.widget.PopularPosts .popular-item{display:flex;gap:16px;padding-bottom:18px}
.widget.PopularPosts .popular-item+.popular-item{border-top:1px solid $(border.color);padding-top:18px}
.widget.PopularPosts .item-thumbnail{flex:0 0 84px}
.widget.PopularPosts .item-thumbnail img{aspect-ratio:1/1;height:84px;object-fit:cover;width:84px}
.widget.PopularPosts .item-title{font-family:$(posts.title.font.family);font-size:16.5px;line-height:1.65;margin:0 0 6px}
.widget.PopularPosts .item-title a{color:$(posts.title.color)}
.widget.PopularPosts .item-title a:hover{color:$(keycolor)}
.widget.PopularPosts .item-meta{color:$(muted.color);font-size:12.5px}
.widget.PopularPosts .item-number{
  color:$(keycolor);font-family:$(posts.title.font.family);font-size:26px;flex:0 0 34px;line-height:1
}

/* التسميات */
.widget.Label .label-list{display:flex;flex-wrap:wrap;gap:9px}
.widget.Label .label-list li{margin:0}
.widget.Label .label-list a{
  border:1px solid $(border.color);border-radius:999px;display:inline-block;font-size:13.5px;padding:4px 14px;transition:all .2s ease
}
.widget.Label .label-list a:hover{background:$(keycolor);border-color:$(keycolor);color:#fff}
.widget.Label .label-count{color:$(muted.color);font-size:12px;margin-inline-start:6px}
.widget.Label .cloud-label-widget-content{display:flex;flex-wrap:wrap;gap:9px;line-height:1.6}
.widget.Label .cloud-label-widget-content .label-size{
  border:1px solid $(border.color);border-radius:999px;padding:4px 14px;transition:all .2s ease
}
.widget.Label .cloud-label-widget-content .label-size:hover{background:$(keycolor);border-color:$(keycolor)}
.widget.Label .cloud-label-widget-content .label-size:hover a{color:#fff}

/* الأرشيف */
.widget.BlogArchive select{background:$(posts.background.color);border:1px solid $(border.color);color:$(body.text.color);font:inherit;padding:8px 10px;width:100%}
.widget.BlogArchive .archive-list li{align-items:center;display:flex;justify-content:space-between}
.widget.BlogArchive .archive-list a{flex:1}
.widget.BlogArchive .post-count{color:$(muted.color);font-size:12.5px;margin-inline-start:8px}
.widget.BlogArchive details summary{cursor:pointer;list-style:none}
.widget.BlogArchive details summary::-webkit-details-marker{display:none}
.widget.BlogArchive .hierarchy{list-style:none;padding-inline-start:0}
.widget.BlogArchive .hierarchy ul{padding-inline-start:1.1em}

/* قائمة الروابط والتنقل */
.LinkList ul li,.PageList ul li{list-style:none}
.widget.LinkList a{border-bottom:1px dashed transparent;display:inline-block;padding-bottom:2px}
.widget.LinkList a:hover{border-bottom-color:$(keycolor)}

/* البحث في الشريط الجانبي */
.widget.BlogSearch form{display:flex;gap:8px}
.widget.BlogSearch input[name=q]{
  background:transparent;border:1px solid $(border.color);color:$(body.text.color);
  flex:1;font:inherit;font-size:14.5px;min-width:0;outline:0;padding:9px 14px
}
.widget.BlogSearch input[type=submit],.widget.BlogSearch button{
  background:$(posts.title.color);border:0;color:#fff;cursor:pointer;font:inherit;font-size:14px;padding:9px 18px
}
.widget.BlogSearch input[type=submit]:hover,.widget.BlogSearch button:hover{background:$(keycolor)}

/* الأرشفة والإسناد */
.widget.Attribution{background:0 0;border:0;padding:0}
.widget.Attribution .blogger a{align-items:center;display:inline-flex;gap:8px}
.widget.Attribution svg{height:16px;width:16px}

/* ============================================================
   8) التعليقات
   ============================================================ */
#comments{margin-top:44px}
#comments .comments-title{
  font-family:$(posts.title.font.family);font-size:20px;margin:0 0 24px;padding-bottom:14px;
  position:relative
}
#comments .comments-title::after{background:$(keycolor);bottom:0;content:"";height:2px;inset-inline-start:0;position:absolute;width:40px}
#comments .comment{list-style:none;margin:0;padding:0 0 26px;position:relative}
#comments ol{list-style:none;margin:0;padding:0}
#comments .comment-block{border-bottom:1px solid $(border.color);padding-bottom:22px}
#comments .comment+.comment .comment-block,#comments .comment .comment .comment-block{border-bottom:0}
#comments .comment-replies{border-inline-start:2px solid $(border.color);margin-inline-start:22px;padding-inline-start:22px}
#comments .comment-header{align-items:flex-start;display:flex;gap:14px;margin-bottom:10px}
#comments .avatar-image-container{flex:0 0 42px}
#comments .avatar-image-container img{border-radius:50%;height:42px;width:42px}
#comments .avatar-icon{color:$(border.color);height:42px;width:42px}
#comments .comment-author,#comments .comment-author a{color:$(posts.title.color);font-weight:700}
#comments .datetime,#comments .comment-timestamp a{color:$(muted.color);font-size:12.5px}
#comments .comment-content{color:$(body.text.color);line-height:1.9}
#comments .comment-content p:last-child{margin-bottom:0}
#comments .comment-actions a,#comments .comment-reply{
  color:$(keycolor);font-size:13px;letter-spacing:.02em
}
#comments .comment-actions>*{margin-inline-end:12px}
.comments .comments-content .loadmore{display:none}
.comment-form h4,#comments h3.title{
  border:0;clip:rect(1px,1px,1px,1px);height:1px;overflow:hidden;padding:0;position:absolute;width:1px
}
#comment-editor{border:0;margin-top:18px;width:100%}
.comment-footer{margin-top:26px}
#comment-holder .continue{display:none}
.blogger-iframe-colorize{margin-top:16px}
.paging-control-container{color:$(muted.color);font-size:14px;margin:18px 0;text-align:center}
.paging-control-container a{margin-inline-end:12px}

/* ============================================================
   9) التذييل
   ============================================================ */
.site-footer{background:$(footer.background.color);color:$(footer.text.color);margin-top:20px;padding-top:56px}
.site-footer a{color:$(footer.link.color)}
.site-footer a:hover{color:$(keycolor)}
.footer-widgets{display:grid;gap:34px;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));padding-bottom:44px}
.site-footer .widget{background:0 0;border:0;margin:0;padding:0}
.site-footer .widget .widget-title{color:#fff;text-align:start}
.site-footer .widget .widget-title span{color:#fff}
.site-footer .widget .widget-title::after{left:0;transform:none;background:$(keycolor)}
.site-footer .widget a{color:$(footer.link.color)}
.site-footer .widget .label-list a,.site-footer .widget .cloud-label-widget-content .label-size{border-color:rgba(255,255,255,.22);color:$(footer.link.color)}
.site-footer .widget .label-list a:hover,.site-footer .widget .cloud-label-widget-content .label-size:hover{background:$(keycolor);border-color:$(keycolor)}
.site-footer .widget .label-list a:hover,.site-footer .widget .label-list a:hover *{color:#fff}
.footer-bottom{
  border-top:1px solid rgba(255,255,255,.12);color:$(footer.text.color);font-size:13.5px;
  padding-block:24px 26px;text-align:center
}
.footer-bottom .footer-note{opacity:.85}
.footer-bottom .Attribution{margin-top:10px}
.to-top{
  align-items:center;background:$(keycolor);border-radius:50%;bottom:26px;color:#fff;display:flex;
  height:44px;inset-inline-end:24px;justify-content:center;position:fixed;width:44px;z-index:90;
  box-shadow:0 10px 24px -12px rgba(0,0,0,.6);opacity:.9;transition:opacity .2s ease,transform .2s ease
}
.to-top:hover{color:#fff;opacity:1;transform:translateY(-3px)}
.to-top.is-hidden{opacity:0;visibility:hidden;pointer-events:none}
.to-top svg{height:20px;width:20px}

/* ============================================================
   10) إصلاحات بلوجر
   ============================================================ */
.post-body .snippet-thumbnail{float:none;margin:0}
body.item-view .post-body a[imageanchor="1"]{margin:0 auto!important}
.site-header .widget,.site-nav .widget,#page_body .widget{background:0 0;border:0;margin:0;padding:0}
.icon-close{display:none}
.ornament-diamond{fill:currentColor;stroke:none}
.default-avatar{color:$(border.color);height:104px;width:104px}
.profile-image-link{display:inline-block}
.comment-info{flex:1;min-width:0}
.section,.widget{margin:0}
.centered-bottom .widget{margin-bottom:30px}
.disqus_thread{margin-top:30px}
iframe.blogger-iframe-colorize{width:100%}
#comment-editor-src{display:none}
.post-body .jump-link{margin-top:10px}
.screen-reader-text{border:0;clip:rect(1px,1px,1px,1px);height:1px;overflow:hidden;position:absolute;width:1px}

/* ============================================================
   11) الاستجابة (Responsive)
   ============================================================ */
@media (max-width:1000px){
  .layout-grid{gap:36px;grid-template-columns:minmax(0,1fr)}
  .sidebar{margin-top:8px}
  .site-nav{position:relative}
  .nav-inner{justify-content:space-between;min-height:56px;padding-inline:10px}
  .nav-toggle{display:flex}
  .nav-search{flex-basis:auto;flex-grow:1}
  .site-nav .widget,.site-nav .section{display:none}
  .nav-toggle-checkbox:checked~.section{display:block;flex:0 0 100%;order:3}
  .nav-toggle-checkbox:checked~.section ul{display:block;padding-block:8px 14px;width:100%}
  .nav-toggle-checkbox:checked~.section li a{border-bottom:1px solid $(border.color);padding:13px 4px}
  .nav-toggle-checkbox:checked~.nav-toggle .icon-close{display:inline-block}
  .nav-toggle-checkbox:checked~.nav-toggle .icon-menu{display:none}
}
@media (max-width:760px){
  .header-inner{padding-block:34px 28px}
  .post-card{grid-template-columns:minmax(0,1fr)}
  .post-card .post-thumb img{aspect-ratio:16/9}
  .post-card .post-body-wrap{padding:24px 22px 26px}
  .post-card .entry-title{font-size:22px}
  .entry{padding:30px 20px 26px}
  .entry-title{font-size:$(posts.title.font.size * 0.72)}
  .entry-content{font-size:$(body.text.font.size * 1.0)}
  .post-pager{grid-template-columns:minmax(0,1fr)}
  .author-box{flex-direction:column;text-align:center}
  .site-main{padding-block:30px 40px}
}
@media (max-width:760px){
  .search-hint{display:none}
  .nav-search button{flex:0 0 34px;height:34px;width:34px}
  .nav-search input{font-size:14px;padding:7px 12px}
}
@media (max-width:420px){
  .nav-search button{flex:0 0 32px;height:32px;width:32px}
  .nav-search input{font-size:13.5px;padding:6px 10px}
  .blog-pager{flex-direction:column;align-items:stretch;text-align:center}
  .blog-pager a{display:block}
}

/* ============================================================
   12) الطباعة
   ============================================================ */
@media print{
  .site-nav,.sidebar,.site-footer,.to-top,.share-box,.skip-link,.post-pager,.blog-pager{display:none!important}
  .layout-grid{display:block}
  body{background:#fff;color:#000}
  .entry,.post-card{border:0;box-shadow:none}
  a{color:#000;text-decoration:underline}
}

head.b:template-skin:
body#layout .skip-link,
body#layout .to-top,
body#layout .nav-toggle,
body#layout .nav-search,
body#layout .header-ornament,
body#layout .share-box,
body#layout .post-pager,
body#layout .entry-divider {
  display: none;
}
body#layout .layout-grid {
  display: block;
}
body#layout .content-area,
body#layout .sidebar {
  display: inline-block;
  vertical-align: top;
}
body#layout .content-area {
  width: 62%;
}
body#layout .sidebar {
  width: 35%;
  margin-inline-start: 2%;
}
body#layout .section h4 {
  display: none;
}
body#layout .widget {
  margin-bottom: 14px;
  padding: 10px;
}
body#layout .widget .widget-title {
  margin: 0 0 8px;
  padding: 0;
  text-align: start;
}
body#layout .widget .widget-title::after {
  display: none;
}
body#layout .site-header,
body#layout .site-nav {
  padding: 6px 0;
}
body#layout .site-nav {
  position: static;
}
body#layout .nav-menu,
body#layout .nav-menu .widget {
  display: block !important;
}
body#layout:before {
  color: #9c7c48;
  content: "Dahsha Muthaqa - Theme 1.1";
  display: block;
  font: 700 14px/1 sans-serif;
  padding: 14px 10px;
}

body.script:
//
(function () {
  var y = document.getElementById('dahsha-year');
  if (y) { y.textContent = new Date().getFullYear(); }
  var t = document.querySelector('.to-top');
  if (t) {
    var update = function () {
      if (window.scrollY > 420) { t.classList.remove('is-hidden'); }
      else { t.classList.add('is-hidden'); }
    };
    window.addEventListener('scroll', update, { passive: true });
    update();
  }
})();
//
